import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { charge } from "@/lib/billing";
import { enqueue } from "@/lib/jobs";
import { log } from "@/lib/log";

const Body = z.object({ prompt: z.string().min(1), model: z.string(), idempotencyKey: z.string().optional() });

export async function POST(req: NextRequest) {
  const parsed = Body.safeParse(await req.json());
  if (!parsed.success) return NextResponse.json({ error: "invalid body", code: "bad_request" }, { status: 400 });
  const { prompt, model, idempotencyKey } = parsed.data;
  const user = await getUser(req);
  const ok = await charge(user.id, priceFor(model));
  if (!ok) return NextResponse.json({ error: "not enough gems", code: "payment_required" }, { status: 402 });
  const job = await enqueue({ userId: user.id, prompt, model, idempotencyKey });
  log.info("generate", { userId: user.id, model, jobId: job.id });
  return NextResponse.json({ jobId: job.id });
}
